INSERT INTO questions (mode, class_id, public, active, data, created_at, skill, min_floor, max_floor, rules) SELECT 4, NULL, 1, 1, '{"stem":"Which TWO details show Tally needs help?","options":[{"id":"a","text":"wobbling"},{"id":"b","text":"her legs are shaking"},{"id":"c","text":"gasped"},{"id":"d","text":"let Mei take one end"},{"id":"e","text":"Mei stepped forward"},{"id":"f","text":"the crate is mentioned"}],"correct":["a","b","c","d"],"pick":2,"explanation":"Wobbling, shaking legs, gasping and handing over one end all show she is struggling. Mei stepping forward is Mei’s action, and the crate being mentioned is not a clue.","passage":"“I don’t need any help,” said Tally, wobbling under the large crate.\nMei stepped forward. “Your legs are shaking.”\n“They’re just cold,” Tally gasped, but she let Mei take one end.","group":"rb-tally","code":"MC_INFER","seed":"sk-x-7-3b"}', 1792296240907, 'reading_between', NULL, NULL, 8192 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE json_extract(data, '$.seed') = 'sk-x-7-3b');
