INSERT INTO questions (mode, class_id, public, active, data, created_at, skill, min_floor, max_floor, rules) SELECT 4, NULL, 1, 1, '{"stem":"How does Chen really feel about being left behind?","options":[{"id":"a","text":"delighted"},{"id":"b","text":"relaxed"},{"id":"c","text":"curious"},{"id":"d","text":"hurt and left out"}],"correct":["d"],"pick":1,"explanation":"His words say he doesn’t mind, but staring at his shoes, mumbling and sighing show he is hurt.","passage":"“I don’t mind if you go without me,” said Chen, staring at his shoes.\nNoor tilted her head. “You’ve said that three times.”\n“Go on, have fun,” Chen mumbled, and he sighed.","group":"rb-chen","code":"MC_INFER","seed":"sk-x-7-4a"}', 1792296240907, 'reading_between', NULL, NULL, 8192 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE json_extract(data, '$.seed') = 'sk-x-7-4a');
INSERT INTO questions (mode, class_id, public, active, data, created_at, skill, min_floor, max_floor, rules) SELECT 4, NULL, 1, 1, '{"stem":"Which TWO details show Chen minds being left behind?","options":[{"id":"a","text":"staring at his shoes"},{"id":"b","text":"he says it three times"},{"id":"c","text":"mumbled"},{"id":"d","text":"sighed"},{"id":"e","text":"Noor tilted her head"},{"id":"f","text":"Chen speaks to Noor"}],"correct":["a","b","c","d"],"pick":2,"explanation":"Looking down, repeating himself, mumbling and sighing show his real feelings. Noor’s head tilt is her reaction, and who he speaks to tells us nothing.","passage":"“I don’t mind if you go without me,” said Chen, staring at his shoes.\nNoor tilted her head. “You’ve said that three times.”\n“Go on, have fun,” Chen mumbled, and he sighed.","group":"rb-chen","code":"MC_INFER","seed":"sk-x-7-4b"}', 1792296240907, 'reading_between', NULL, NULL, 8192 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE json_extract(data, '$.seed') = 'sk-x-7-4b');
INSERT INTO questions (mode, class_id, public, active, data, created_at, skill, min_floor, max_floor, rules) SELECT 4, NULL, 1, 1, '{"stem":"Why does Noor tilt her head?","options":[{"id":"a","text":"she is about to sneeze"},{"id":"b","text":"she doesn’t quite believe him and is gently checking"},{"id":"c","text":"she is listening for a noise"},{"id":"d","text":"she wants to leave"}],"correct":["b"],"pick":1,"explanation":"A tilted head shows curiosity and doubt. Noor notices his words don’t match his mood.","passage":"“I don’t mind if you go without me,” said Chen, staring at his shoes.\nNoor tilted her head. “You’ve said that three times.”\n“Go on, have fun,” Chen mumbled, and he sighed.","group":"rb-chen","code":"MC_INFER","seed":"sk-x-7-4c"}', 1792296240907, 'reading_between', NULL, NULL, 8192 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE json_extract(data, '$.seed') = 'sk-x-7-4c');
INSERT INTO questions (mode, class_id, public, active, data, created_at, skill, min_floor, max_floor, rules) SELECT 4, NULL, 1, 1, '{"stem":"How does Brisk really feel about the game?","options":[{"id":"a","text":"it matters a lot to her"},{"id":"b","text":"she doesn’t care"},{"id":"c","text":"she is bored"},{"id":"d","text":"she is sleepy"}],"correct":["a"],"pick":1,"explanation":"She says it’s only a game, but the tight grip, white knuckles and shaking hand show it matters to her.","passage":"“It’s only a game,” said Brisk, but she gripped the board tightly.\nWren grinned. “Then why are your knuckles white?”\n“Be quiet,” Brisk muttered, and she moved her piece with a shaking hand.","group":"rb-brisk","code":"MC_INFER","seed":"sk-x-7-5a"}', 1792296240907, 'reading_between', NULL, NULL, 8192 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE json_extract(data, '$.seed') = 'sk-x-7-5a');
INSERT INTO questions (mode, class_id, public, active, data, created_at, skill, min_floor, max_floor, rules) SELECT 4, NULL, 1, 1, '{"stem":"Which TWO details show the game matters to Brisk?","options":[{"id":"a","text":"gripped the board tightly"},{"id":"b","text":"her knuckles are white"},{"id":"c","text":"muttered"},{"id":"d","text":"a shaking hand"},{"id":"e","text":"Wren grinned"},{"id":"f","text":"a board game is mentioned"}],"correct":["a","b","c","d"],"pick":2,"explanation":"Gripping, white knuckles, muttering and a shaking hand all show strong feeling. Wren’s grin is his reaction, and a board game being mentioned is not a clue.","passage":"“It’s only a game,” said Brisk, but she gripped the board tightly.\nWren grinned. “Then why are your knuckles white?”\n“Be quiet,” Brisk muttered, and she moved her piece with a shaking hand.","group":"rb-brisk","code":"MC_INFER","seed":"sk-x-7-5b"}', 1792296240907, 'reading_between', NULL, NULL, 8192 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE json_extract(data, '$.seed') = 'sk-x-7-5b');
INSERT INTO questions (mode, class_id, public, active, data, created_at, skill, min_floor, max_floor, rules) SELECT 4, NULL, 1, 1, '{"stem":"Why does Wren grin?","options":[{"id":"a","text":"he is losing"},{"id":"b","text":"he is angry"},{"id":"c","text":"to tease her gently because he has spotted that she cares"},{"id":"d","text":"he wants to cheat"}],"correct":["c"],"pick":1,"explanation":"A grin and a teasing question show Wren has noticed her real feelings and is playfully pointing them out.","passage":"“It’s only a game,” said Brisk, but she gripped the board tightly.\nWren grinned. “Then why are your knuckles white?”\n“Be quiet,” Brisk muttered, and she moved her piece with a shaking hand.","group":"rb-brisk","code":"MC_INFER","seed":"sk-x-7-5c"}', 1792296240907, 'reading_between', NULL, NULL, 8192 WHERE NOT EXISTS (SELECT 1 FROM questions WHERE json_extract(data, '$.seed') = 'sk-x-7-5c');
